class NumberContainers {
    private java.util.HashMap<Integer, Integer> indexToNum;
    private java.util.HashMap<Integer, java.util.TreeSet<Integer>> numToIndices;

    public NumberContainers() {
        indexToNum = new java.util.HashMap<>();
        numToIndices = new java.util.HashMap<>();
    }

    public void change(int index, int number) {
        if (indexToNum.containsKey(index)) {
            int oldNum = indexToNum.get(index);
            numToIndices.get(oldNum).remove(index);
            if (numToIndices.get(oldNum).isEmpty()) numToIndices.remove(oldNum);
        }
        indexToNum.put(index, number);
        numToIndices.computeIfAbsent(number, k -> new java.util.TreeSet<>()).add(index);
    }

    public int find(int number) {
        if (!numToIndices.containsKey(number) || numToIndices.get(number).isEmpty()) return -1;
        return numToIndices.get(number).first();
    }
}
